1	package com.example.starter.race.persistence;
2	
3	import com.example.starter.race.domain.EntryStatus;
4	import com.example.starter.race.domain.PenaltyType;
5	import com.example.starter.race.domain.RaceStatus;
6	import org.springframework.jdbc.core.JdbcTemplate;
7	import org.springframework.jdbc.core.RowMapper;
8	import org.springframework.stereotype.Repository;
9	
10	import java.sql.ResultSet;
11	import java.sql.SQLException;
12	import java.util.List;
13	import java.util.Optional;
14	
15	/**
16	 * 赛事封榜领域的 JDBC 仓储；所有写方法均假定运行在业务事务内，
17	 * 版本推进与封榜全部使用条件 UPDATE 保证并发下无丢失更新。
18	 */
19	@Repository
20	public class RaceRepository {
21	
22	    private static final RaceRowMapper RACE_ROW_MAPPER = new RaceRowMapper();
23	    private static final RunnerRowMapper RUNNER_ROW_MAPPER = new RunnerRowMapper();
24	    private static final PenaltyRowMapper PENALTY_ROW_MAPPER = new PenaltyRowMapper();
25	    private static final SnapshotEntryRowMapper SNAPSHOT_ENTRY_ROW_MAPPER =
26	            new SnapshotEntryRowMapper();
27	    private static final IdempotencyRowMapper IDEMPOTENCY_ROW_MAPPER = new IdempotencyRowMapper();
28	
29	    private final JdbcTemplate jdbcTemplate;
30	
31	    public RaceRepository(JdbcTemplate jdbcTemplate) {
32	        this.jdbcTemplate = jdbcTemplate;
33	    }
34	
35	    /** 按ID查询赛事。 */
36	    public Optional<RaceRow> findRace(String raceId) {
37	        return jdbcTemplate
38	                .query("SELECT race_id, version, status, created_at FROM race WHERE race_id = ?",
39	                        RACE_ROW_MAPPER, raceId)
40	                .stream()
41	                .findFirst();
42	    }
43	
44	    /** 查询赛事下全部选手，按参赛号字典序排列。 */
45	    public List<RunnerRow> findRunners(String raceId) {
46	        return jdbcTemplate.query(
47	                "SELECT id, race_id, bib, finish_time_ms, created_at, updated_at "
48	                        + "FROM runner WHERE race_id = ? ORDER BY bib",
49	                RUNNER_ROW_MAPPER, raceId);
50	    }
51	
52	    /** 按赛事与参赛号查询选手。 */
53	    public Optional<RunnerRow> findRunner(String raceId, String bib) {
54	        return jdbcTemplate
55	                .query("SELECT id, race_id, bib, finish_time_ms, created_at, updated_at "
56	                                + "FROM runner WHERE race_id = ? AND bib = ?",
57	                        RUNNER_ROW_MAPPER, raceId, bib)
58	                .stream()
59	                .findFirst();
60	    }
61	
62	    /** 查询赛事下全部处罚（含已撤销），按新增时间与处罚ID排列。 */
63	    public List<PenaltyRow> findPenalties(String raceId) {
64	        return jdbcTemplate.query(
65	                "SELECT penalty_id, race_id, bib, type, amount_ms, revoked, created_at, revoked_at "
66	                        + "FROM penalty WHERE race_id = ? ORDER BY created_at, penalty_id",
67	                PENALTY_ROW_MAPPER, raceId);
68	    }
69	
70	    /** 按全局处罚ID查询处罚。 */
71	    public Optional<PenaltyRow> findPenalty(String penaltyId) {
72	        return jdbcTemplate
73	                .query("SELECT penalty_id, race_id, bib, type, amount_ms, revoked, created_at, revoked_at "
74	                                + "FROM penalty WHERE penalty_id = ?",
75	                        PENALTY_ROW_MAPPER, penaltyId)
76	                .stream()
77	                .findFirst();
78	    }
79	
80	    /** 查询封榜快照（含全部条目）；未封榜返回 empty。 */
81	    public Optional<SnapshotRow> findSnapshot(String raceId) {
82	        List<SnapshotRow> headers = jdbcTemplate.query(
83	                "SELECT race_id, version, sealed_at FROM result_snapshot WHERE race_id = ?",
84	                (rs, rowNum) -> new SnapshotRow(
85	                        rs.getString("race_id"),
86	                        rs.getInt("version"),
87	                        rs.getLong("sealed_at"),
88	                        List.of()),
89	                raceId);
90	        if (headers.isEmpty()) {
91	            return Optional.empty();
92	        }
93	        SnapshotRow header = headers.getFirst();
94	        List<SnapshotEntryRow> entries = jdbcTemplate.query(
95	                "SELECT race_id, bib, rank_no, status, finish_time_ms, penalty_ms, total_time_ms, display_order "
96	                        + "FROM result_snapshot_entry WHERE race_id = ? ORDER BY display_order",
97	                SNAPSHOT_ENTRY_ROW_MAPPER, raceId);
98	        return Optional.of(new SnapshotRow(header.raceId(), header.version(), header.sealedAt(),
99	                entries));
100	    }
101	
102	    /** 新建赛事，初始版本1、状态OPEN。 */
103	    public void insertRace(String raceId, long now) {
104	        jdbcTemplate.update(
105	                "INSERT INTO race (race_id, version, status, created_at) VALUES (?, 1, 'OPEN', ?)",
106	                raceId, now);
107	    }
108	
109	    /** 登记选手；finishTimeMs 为 null 表示计时缺失。 */
110	    public void insertRunner(String raceId, String bib, Long finishTimeMs, long now) {
111	        jdbcTemplate.update(
112	                "INSERT INTO runner (race_id, bib, finish_time_ms, created_at, updated_at) "
113	                        + "VALUES (?, ?, ?, ?, ?)",
114	                raceId, bib, finishTimeMs, now, now);
115	    }
116	
117	    /** 修订选手原始完赛耗时；返回受影响行数（0 表示选手不存在）。 */
118	    public int updateRunnerTiming(String raceId, String bib, Long finishTimeMs, long now) {
119	        return jdbcTemplate.update(
120	                "UPDATE runner SET finish_time_ms = ?, updated_at = ? WHERE race_id = ? AND bib = ?",
121	                finishTimeMs, now, raceId, bib);
122	    }
